const raw = $json.text;

if (!raw) {
  throw new Error('GST Topic Extractor returned no text.');
}

let cleaned = String(raw).trim();

// Remove markdown JSON fences if the model adds them
cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    'GST Topic Extractor did not return valid JSON. Output was:\n' + cleaned
  );
}

if (!Array.isArray(parsed.topics)) {
  throw new Error('No topics array found in GST Topic Extractor output.');
}

return parsed.topics.map(topic => ({
  json: {
    source_document: parsed.source_document || 'The GST Insider 33rd Edition.pdf',
    topic_id: topic.topic_id,
    topic_title: topic.topic_title,
    topic_type: topic.topic_type,
    source_pages: topic.source_pages,
    case_or_reference: topic.case_or_reference,
    court_or_authority: topic.court_or_authority,
    legal_provisions: topic.legal_provisions || [],
    core_issue: topic.core_issue,
    key_facts: topic.key_facts,
    decision_or_development: topic.decision_or_development,
    practical_significance: topic.practical_significance,
    source_summary: topic.source_summary,
    status: 'AVAILABLE'
  }
}));
